 return $s.'</select></label><label>LRN (12 digits)<input name="lrn" type="text" inputmode="numeric" pattern="[0-9]{12}" minlength="12" maxlength="12" value="'.e($p['lrn']??'').'" placeholder="Enter learner reference number"><small>Leave blank if the LRN is not available yet. The pupil login ID stays the same.</small></label>';
}
function avatar_picker(array $u):void{
 $choices=profile_avatar_choices();$selected='';foreach($choices as $key=>$v)if(($u['avatar_path']??'')==='assets/avatars/'.$key.'.png')$selected=$key;
 echo '<section class="card avatar-picker"><span class="eyebrow">A LITTLE PICTURE OF YOU</span><h2>Choose your profile picture</h2><p>Pick a character you like, or upload your own photo below.</p><form method="post">'.csrf_field().'<input type="hidden" name="action" value="choose_avatar"><fieldset><legend>Choose one of six characters</legend><div class="avatar-options">';
 foreach($choices as $key=>$v)echo '<label class="avatar-option"><input type="radio" name="avatar_key" value="'.$key.'" '.($selected===$key?'checked':'').' required><span class="avatar-option-picture"><img src="assets/avatars/'.$key.'.png" alt="'.e($v[0]).'" width="120" height="120"><span class="avatar-picked">'.icon('check').'</span></span><span class="avatar-option-label">'.e(explode(' · ',$v[0])[0]).'</span></label>';
 echo '</div></fieldset><button class="btn primary">Use this picture</button></form></section>';
}

function pupil_next_step(int $pid):void{
 $next=next_learning_lesson($pid);
 echo '<section class="next-adventure"><div class="adventure-copy"><span class="adventure-tag">'.icon('book').' YOUR LEARNING ADVENTURE</span><h2>'.($next?'A little practice.<br>A brighter day.':'Every step helps you grow.').'</h2><p>'.($next?'Next up: '.e(level_label((int)$next['level_id']).' · '.$next['subtitle']).'.':'Explore your available levels below. Your teacher can choose your starting level.').'</p>';
 if($next)echo '<a class="btn primary" href="?page=lesson&id='.(int)$next['id'].'">Let’s keep learning '.icon('arrow').'</a><a class="adventure-link" href="?page=dashboard&level='.$next['level_id'].'">See my learning path</a>';
 echo '</div><div class="adventure-art"><img src="assets/design/reading-garden.svg" alt="An open book in a leafy learning garden"><span class="adventure-note">One small step, every day</span></div></section>';
}

function narration_controls(string $text):void{
 echo '<div class="narration" data-text="'.e($text).'"><button type="button" class="btn quiet" data-speech="play">'.icon('sound').'Listen</button><button type="button" class="iconbutton light" data-speech="pause" aria-label="Pause or resume">'.icon('pause').'</button><button type="button" class="iconbutton light" data-speech="replay" aria-label="Replay">'.icon('replay').'</button><button type="button" class="iconbutton light" data-speech="stop" aria-label="Stop">'.icon('stop').'</button><button type="button" class="iconbutton light" data-speech="mute" aria-label="Mute narration" aria-pressed="false">'.icon('mute').'</button><details class="voice-settings"><summary>Voice</summary><select id="voice-select" aria-label="Narration voice"></select><small id="voice-info">Available voices depend on your device.</small></details></div>';
